// Тикеты #6a86f7fa #3cc72778. Геометрия «кружок с иконкой справа» (Figma 608:1389) на устройстве не измеряется — ручная проверка по скриншоту.
import { expect } from '@wdio/globals';
import { byText, byLabel, byTextMatches, byTextContains, expectVisibleText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

describe('Напоминания', () => {
  afterEach(async () => { await toHome(); });

  it('RM-01 «תזכורות מהירות» — строки с пояснением, ближайшая молитва с окном HH:MM, «ניהול תזכורות» #6a86f7fa #3cc72778 @prod-safe', async () => {
    // 1. Главная → блок «תזכורות מהירות».
    await toHome();
    await (await byText('תזכורות מהירות')).waitForDisplayed({ timeout: 20000 });

    // «ניהול תזכורות» (a11y «ניהול התזכורות במסך הפרופיל»).
    const manage = await byLabel('ניהול התזכורות במסך הפרופיל');
    await expect(manage).toBeDisplayed();
    await expectVisibleText('ניהול תזכורות');

    // Строка ближайшей молитвы содержит время окончания окна HH:MM.
    await expect(byTextMatches('.*\\d{2}:\\d{2}.*')).toBeDisplayed();

    // Нет «undefined»/«null»/«NaN» на экране.
    for (const bad of ['undefined', 'null', 'NaN']) {
      await expect(byTextContains(bad)).not.toBeDisplayed();
    }
  });
});
